DROP TABLE IF EXISTS `dare_classes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dare_classes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `access_dareclass_id` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `school_id` int unsigned NOT NULL,
  `teacher_id` int unsigned DEFAULT NULL,
  `officer_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `school_year` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `class_name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `semester` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `period` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `graduation_date` date DEFAULT NULL,
  `status` enum('active','completed','graduated','closed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `access_dareclass_id` (`access_dareclass_id`),
  KEY `idx_dare_class_dates` (`start_date`,`end_date`),
  KEY `idx_dare_class_status` (`status`),
  KEY `fk_dare_classes_school` (`school_id`),
  KEY `fk_dare_classes_teacher` (`teacher_id`),
  KEY `fk_dare_classes_officer` (`officer_id`),
  KEY `fk_dare_classes_created_by` (`created_by`)
) ENGINE=MyISAM AUTO_INCREMENT=500 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
