--
-- Table structure for table `dmv_records`
--

DROP TABLE IF EXISTS `dmv_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dmv_records` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `created_by` int unsigned DEFAULT NULL,
  `transaction_date` date NOT NULL,
  `customer_name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `street_address` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `zip_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transaction_type` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `plate_or_vin` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_dmv_transaction_date` (`transaction_date`),
  KEY `idx_dmv_customer_name` (`customer_name`),
  KEY `idx_dmv_transaction_type` (`transaction_type`),
  KEY `fk_dmv_records_created_by` (`created_by`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `dmv_records`
--

LOCK TABLES `dmv_records` WRITE;
/*!40000 ALTER TABLE `dmv_records` DISABLE KEYS */;
/*!40000 ALTER TABLE `dmv_records` ENABLE KEYS */;
UNLOCK TABLES;

