  `created_by` int unsigned DEFAULT NULL,
  `request_date` date NOT NULL,
  `registrant_name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `registrant_name_2` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
