INSERT INTO `election_settings` VALUES ('access_email_subject','Election training access for [Election Name]','2026-08-03 19:19:08'),('access_email_body','Hello [Worker Name],\r\n\r\nYou have been added as an election worker for [Election Name].\r\n\r\nUse this access link to review your information and sign up for an available training class:\r\n\r\n[Access Link]\r\n\r\nThis link is intended for you only. Do not share this link with anyone. It remains active through the election period unless a supervisor sends a replacement link. If you receive a replacement link, this link will no longer be valid and should be destroyed.\r\n\r\nThank you.','2026-08-03 19:19:08');
